using System;using System.IO;using System.Linq;using System.Collections.Generic;using BeamScheduleFormatter;
class EngineeringQuantityPdfTests {
 static int checks;static void Check(bool value,string name){checks++;if(!value)throw new Exception(name);}
 static void Main(string[] args){var register=typeof(System.Text.Encoding).GetMethod("RegisterProvider");if(register!=null){var type=System.Reflection.Assembly.Load("System.Text.Encoding.CodePages").GetType("System.Text.CodePagesEncodingProvider");register.Invoke(null,new[]{type.GetProperty("Instance").GetValue(null,null)});}string directory=args.Length>0?Path.GetFullPath(args[0]):Path.GetTempPath();Directory.CreateDirectory(directory);var report=new EngineeringReport{Title="Quantity take-off report",Project="Illustrative engineering report — example data",Location="Sample project; quantities below are test fixtures",Office="DTCE Engineering",Subtitle="Bill of Quantities · source breakdown · measurement inputs"};
  var boq=report.Section("Bill of Quantities");boq.Table(new[]{"Pay item","Description","Quantity","Unit"},new[]{new[]{"105(1)a","Subgrade Preparation (Common Material)","80","sq.m."},new[]{"102(2)","Roadway Excavation (Surplus Common)","12","cu.m."},new[]{"311(1)a","0.15m thk. Portland Cement Concrete Pavement (Unreinforced)","80","sq.m."}});
  var section=report.Section("Pavement Construction — source breakdown");section.Table(new[]{"Source / member","Quantity","Unit","Calculation / basis"},new[]{new[]{"SG-001 | Prepared roadway","80","m2","Prepared area = 10 m × 4 m × 2 = 80 m2. No swell or shrink factor is applied."},new[]{"EX-001 | Roadway excavation","12","m3","In-place bank excavation = 10 m × 4 m × 0.15 m × 2 = 12 m3. Swell/shrink factors are separate from the excavation pay quantity."},new[]{"P-001 | PCCP 150 mm","80","m2","Pavement area = 10 m × 4 m × 2 = 80 m2. Reference concrete volume = 80 m2 × 0.15 m = 12 m3; do not duplicate as structural concrete."}});
  var inputs=report.Section("Measurement inputs");inputs.Table(new[]{"Input parameter","Value"},new[]{new[]{"Measured length","10 m"},new[]{"Prepared width","4 m"},new[]{"Quantity","2"},new[]{"Pavement thickness","150 mm"}});inputs.Note("Example data only. This sample demonstrates report formatting and is not an approved project quantity report.");
  string path=Path.Combine(directory,"DTCE-Quantity-Report-Sample-v1.4.50.pdf");EngineeringQuantityPdf.Write(path,report);Check(File.Exists(path)&&new FileInfo(path).Length>1000,"PDF created");string bytes=System.Text.Encoding.ASCII.GetString(File.ReadAllBytes(path));Check(bytes.StartsWith("%PDF-1.6"),"PDF header");Check(bytes.Contains("/Encrypt"),"Print-only security retained");Check(bytes.Contains("/Subtype /Image")&&bytes.Contains("/WMOpacity"),"Edition logo watermark embedded with transparency");Check(bytes.Contains("595.28 841.89"),"A4 media box");Check(report.Sections[0].Records.Single().Rows.Count==3,"Structured table rows retained");Check(EngineeringQuantityPdf.Wrap(new string('W',300),65,9).Count>10,"Long tokens wrapped within column");
  section.Table(new[]{"Source / member","Quantity","Unit","Calculation / basis"},Enumerable.Range(1,110).Select(i=>new[]{"Pagination fixture "+i,"80","m2","Repeated long calculation basis verifies continuation pages and repeated column headings without losing any record."}));EngineeringQuantityPdf.Write(Path.Combine(directory,"DTCE-Quantity-Report-Pagination-Test.pdf"),report);Check(report.Sections[1].Records.Last().Rows.Count==110,"Pagination fixture retains all rows");Console.WriteLine("PASS: "+checks+" structured report, PDF security, wrapping and pagination checks");
 }
}
